local config = {
  ui_story_5054_50540101_1_dialog_content = "<color=#a8886f>The petals burned to ashes before they hit the ground, a reminder of the riot this tranquil garden just went through.</color>",
  ui_story_5054_50540101_2_dialog_content = "<color=#a8886f>The trails, still lined with burgeoning flowers on both sides, cut through labyrinthine doors and lead to a hall with a very tall dome.</color>",
  ui_story_5054_50540101_3_dialog_content = "<color=#a8886f>A maid laid snacks down in a room, then turned and left. Shortly after, chattering could be heard outside the door...</color>",
  ui_story_5054_50540101_4_option_content = "(Eavesdrop)",
  ui_story_5054_50540101_5_dialog_content = "So, is it really Princess Veronica in there?",
  ui_story_5054_50540101_6_dialog_content = "It's true, I saw it with my own eyes.",
  ui_story_5054_50540101_7_dialog_content = "Those fellows look suspicious. Why would Her Highness be with them?",
  ui_story_5054_50540101_8_dialog_content = "Relax, Ms. Rot is with Lady Joshua. It's not our concern.",
  ui_story_5054_50540101_9_dialog_content = "But it's weird, though. Isn't Ms. Rot the City Lord's favorite? Why isn't she at the celebration?",
  ui_story_5054_50540101_10_dialog_content = "Don't you know? Lady Joshua and Ms. Rot are very tight, and it's the City Lord who told Ms. Rot to look after Her Ladyship.",
  ui_story_5054_50540101_11_dialog_content = "But if they're so tight, why would Lady Joshua deliberately send Ms. Rot away?",
  ui_story_5054_50540101_12_dialog_content = "No way! I heard Ms. Rot is not only a distant relative of Lady Joshua, but the last pupil of hers too!",
  ui_story_5054_50540101_13_option_content = "Distant relative...?",
  ui_story_5054_50540101_14_dialog_content = "Yes, but there's probably no blood relations anymore.",
  ui_story_5054_50540101_15_option_content = "Last pupil...?",
  ui_story_5054_50540101_16_dialog_content = "Yes. Ms. Rot was supposedly a child prodigy but had no guidance.",
  ui_story_5054_50540101_17_dialog_content = "Her parents sought out Sir Caleb through connections and fortuitously ran across Lady Joshua.",
  ui_story_5054_50540101_18_dialog_content = "Lady Joshua and Ms. Rot hit it off immediately, so she mentored her for years.",
  ui_story_5054_50540101_19_dialog_content = "Hey, who's asking questions?",
  ui_story_5054_50540101_20_dialog_content = "Wasn't it you?",
  ui_story_5054_50540101_21_dialog_content = "Ahem, shhh—",
  ui_story_5054_50540101_22_dialog_content = "The walls have ears... We'll pick this up later.",
  ui_story_5054_50540102_1_dialog_content = "<color=#a8886f>The blowing breezes quickly break off fresh, luscious leaves and petals.</color>",
  ui_story_5054_50540102_2_dialog_content = "<color=#a8886f>Crunch!</color>",
  ui_story_5054_50540102_3_dialog_content = "<color=#a8886f>A letter with burned edges makes a dry, ear-piercing noise when stepped on.</color>",
  ui_story_5054_50540102_4_dialog_content = "What's this?",
  ui_story_5054_50540102_5_dialog_content = "Did you find something, Caleb?",
  ui_story_5054_50540102_6_dialog_content = "A stack of burned letters, apparently belonging to my sister...",
  ui_story_5054_50540102_7_option_content = "(Picks one up)",
  ui_story_5054_50540102_8_dialog_content = "<color=#a8886f>A few lines of elegant writing are vaguely discernible on the charred sheet.</color>",
  ui_story_5054_50540102_9_dialog_content = "\"Child of Montague...\"",
  ui_story_5054_50540102_10_dialog_content = "I know the handwriting and signature... My father wrote this?!",
  ui_story_5054_50540102_11_dialog_content = "\"In the end, I'm nothing more than a cowardly bookworm.\"",
  ui_story_5054_50540102_12_dialog_content = "\"The only thing I can do is to leave with...\"",
  ui_story_5054_50540102_13_dialog_content = "\"I hope you and the child will live happily ever after.\"",
  ui_story_5054_50540102_14_dialog_content = "Who's the child of Montague?",
  ui_story_5054_50540102_15_dialog_content = "No idea.",
  ui_story_5054_50540102_16_dialog_content = "My father was a compassionate scholar. I wouldn't be surprised if he sponsored other people's children.",
  ui_story_5054_50540102_17_dialog_content = "Ahem.",
  ui_story_5054_50540102_18_dialog_content = "<color=#a8886f>Schwartz lets out faint coughs, but the urgency comes through loud and clear.</color>",
  ui_story_5054_50540102_19_dialog_content = "Let's not worry about that and just go!",
  ui_story_5054_50540103_1_dialog_content = "<color=#a8886f>Whoosh!</color>",
  ui_story_5054_50540103_2_dialog_content = "<color=#a8886f>A young red-headed girl appears out of the blue and stops a young knight rushing toward the main square.</color>",
  ui_story_5054_50540103_3_dialog_content = "(I see two figures blocking the path ahead...)",
  ui_story_5054_50540103_4_dialog_content = "Sharona?",
  ui_story_5054_50540103_5_dialog_content = "I'm sorry, do I know you?",
  ui_story_5054_50540103_6_dialog_content = "Look at you in that ridiculous knight getup! I wish I didn't recognize you, but the horns on your head made it hard not to.",
  ui_story_5054_50540103_7_dialog_content = "Who are you?",
  ui_story_5054_50540103_8_dialog_content = "You really can't tell?",
  ui_story_5054_50540103_9_dialog_content = "I haven't checked out the latest wanted list yet.",
  ui_story_5054_50540103_10_dialog_content = "<color=#a8886f>Flames suddenly manifest behind the girl but then disperse like an exhaled breath.</color>",
  ui_story_5054_50540103_11_dialog_content = "All right, let me tell you a story.",
  ui_story_5054_50540103_12_dialog_content = "A mother with Dragonkin awakened had given birth to two daughters. Her heritage made her lose control and she was put to death by her family.",
  ui_story_5054_50540103_13_dialog_content = "To protect her dragon about to hatch, the older daughter chose to wander until settling in Umbraton. The younger daughter grew up not knowing her mother was killed by her tribe.",
  ui_story_5054_50540103_14_dialog_content = "I'm sorry, I have not heard that story before, but I get the feeling you're that older daughter.",
  ui_story_5054_50540103_15_dialog_content = "What are you doing back in Lumopolis? Are you responsible for what happened in the square?",
  ui_story_5054_50540103_16_dialog_content = "I see they told you absolutely nothing. Well, feel free to keep serving as Lumopolis's puppet.",
  ui_story_5054_50540103_17_dialog_content = "<color=#a8886f>The dejected red-headed girl turns, but Sharona takes aim at her with no intention of letting her leave.</color>",
  ui_story_5054_50540103_18_option_content = "Coming through!",
  ui_story_5054_50540103_19_option_content = "Assassins are here now!",
  ui_story_5054_50540103_20_dialog_content = "What?",
  ui_story_5054_50540103_21_dialog_content = "<color=#a8886f>The red-headed girl disappears in the blink of eye, as all of you run past the befuddled Sharona.</color>",
  ui_story_5054_50540201_1_dialog_content = "<color=#a8886f>Colorful banners and fancy decor make the white city seem much different than usual. You hide behind a huge banner and evade your pursuers.</color>",
  ui_story_5054_50540201_2_dialog_content = "<color=#a8886f>Just when you're deciding whether to come out, several figures happen to stop before the banner...</color>",
  ui_story_5054_50540201_3_dialog_content = "You didn't bring Miss Roshee with you today, Duke Troy?",
  ui_story_5054_50540201_4_dialog_content = "(Roshee? Isn't that Michael's childhood name?)",
  ui_story_5054_50540201_5_dialog_content = "I instructed her to stay home and study. She can partake in such an event when she's older.",
  ui_story_5054_50540201_6_dialog_content = "That very street-roaming, thief-catching, crime-busting Niece Roshee of yours was willing to stay home and study?",
  ui_story_5054_50540201_7_dialog_content = "I must learn child disciplining techniques from you someday, Duke Troy.",
  ui_story_5054_50540201_8_dialog_content = "It's nothing special. Although Roshee is not my own, she is my sister's daughter, with Troy's blood coursing in her veins.",
  ui_story_5054_50540201_9_dialog_content = "Children would know what to do when the time comes.",
  ui_story_5054_50540201_10_dialog_content = "Sir...",
  ui_story_5054_50540201_11_dialog_content = "Why do you look so stressed?",
  ui_story_5054_50540201_12_dialog_content = "Miss Roshee ran away!",
  ui_story_5054_50540201_13_dialog_content = "I'll let you go, Duke Troy. See you on the stand.",
  ui_story_5054_50540201_14_dialog_content = "We shall, Duke Hermes.",
  ui_story_5054_50540201_15_dialog_content = "<color=#a8886f>After Lachon leaves, Otto turns gloomy.</color>",
  ui_story_5054_50540201_16_dialog_content = "How could you bring that up in front of other people, you dreg!",
  ui_story_5054_50540201_17_dialog_content = "I'm sorry, sir, I was in a big hurry... It won't happen again!",
  ui_story_5054_50540201_18_dialog_content = "There won't be a next time!",
  ui_story_5054_50540201_19_dialog_content = "Did Roshee mention where she's going?",
  ui_story_5054_50540201_20_dialog_content = "No... But the maid said she got a note through the window before she left.",
  ui_story_5054_50540201_21_dialog_content = "<color=#a8886f>Otto follows the servant home, but the serenity is immediately disrupted by hustling soldiers and townspeople.</color>",
  ui_story_5054_50540202_1_dialog_content = "<color=#a8886f>Intermittent screams come from the square. Some lucky escapees start airships in their attempt to leave the allegedly safest floating city.</color>",
  ui_story_5054_50540202_2_dialog_content = "<color=#a8886f>Meanwhile, on a hardly noticeable trail, you see two familiar figures.</color>",
  ui_story_5054_50540202_3_dialog_content = "<color=#a8886f>The red-headed girl, Leona, with a letter in hand, is conversing with someone unexpectedly.</color>",
  ui_story_5054_50540202_4_dialog_content = "Halt!",
  ui_story_5054_50540202_5_dialog_content = "What?",
  ui_story_5054_50540202_6_dialog_content = "(They know each other?)",
  ui_story_5054_50540202_7_dialog_content = "Did you incite Roshee to run away from home?",
  ui_story_5054_50540202_8_dialog_content = "If you're alluding to that girl who was talking to me, then you got the wrong person.",
  ui_story_5054_50540202_9_dialog_content = "She mistook me for a Kartima and asked me to give this letter to Sharona Kartima.",
  ui_story_5054_50540202_10_dialog_content = "Hand me the letter.",
  ui_story_5054_50540202_11_dialog_content = "Even though I'm reluctant to help her, I'm sure I don't have to answer to a rude folk.",
  ui_story_5054_50540202_12_dialog_content = "I can't believe there's someone in Lumopolis who doesn't recognize me, Otto Troy...",
  ui_story_5054_50540202_13_dialog_content = "<color=#a8886f>Whoosh!</color>",
  ui_story_5054_50540202_14_dialog_content = "<color=#a8886f>Before Duke Troy is finished, the red-headed girl sets a corner of the letter on fire.</color>",
  ui_story_5054_50540202_15_dialog_content = "What? Arrest her!",
  ui_story_5054_50540202_16_dialog_content = "<color=#a8886f>The burning letter drifts past your eyes, and before it incinerates, you make out some of the writing...</color>",
  ui_story_5054_50540202_17_dialog_content = "\"The Eclipsite incident from a year ago... Behind the scenes... Duke Otto Troy... unbelievable... cannot stay any longer...\"",
  ui_story_5054_50540202_18_dialog_content = "<color=#a8886f>Sizzle...</color>",
  ui_story_5054_50540202_19_dialog_content = "<color=#a8886f>The letter turns to ash, vanishing from the untainted streets of Lumopolis, much like the past.</color>",
  ui_story_5054_50540203_1_dialog_content = "<color=#a8886f>Crash...</color>",
  ui_story_5054_50540203_2_dialog_content = "<color=#a8886f>In the courtyard next to the road, a tower suddenly crumbles. Dust showers the vicinity and obstructs vision.</color>",
  ui_story_5054_50540203_3_dialog_content = "Cough, cough...",
  ui_story_5054_50540203_4_dialog_content = "<color=#a8886f>From a gap in between debris, the coughs of the elderly break the silence.</color>",
  ui_story_5054_50540203_5_dialog_content = "(Who's that in front of him?)",
  ui_story_5054_50540203_6_dialog_content = "Do you still remember me?",
  ui_story_5054_50540203_7_dialog_content = "<color=#a8886f>The old man looks up slowly before looking elsewhere.</color>",
  ui_story_5054_50540203_8_dialog_content = "Don't you remember Leona? You people wanted to crack the dragon egg in my hand...",
  ui_story_5054_50540203_9_dialog_content = "No, not you.",
  ui_story_5054_50540203_10_dialog_content = "<color=#a8886f>The girl freezes like a statue, speechless for a long pause...</color>",
  ui_story_5054_50540203_11_dialog_content = "Heh, the last time I heard something this absurd, I was just four, five years old. Now, I can't be swayed so easily.",
  ui_story_5054_50540203_12_dialog_content = "Even if you keep babbling to me that \"You're not the one to save the Kartimas\" like my mother whom you deemed mad...",
  ui_story_5054_50540203_13_dialog_content = "You're not the one to save the Kartimas... Neither is Mime...",
  ui_story_5054_50540203_14_dialog_content = "She will show herself soon! She is coming!",
  ui_story_5054_50540203_15_dialog_content = "<color=#a8886f>The red-headed girl falls silent again, but only for a second, until she bursts out in laughter filled with pity and sorrow that echo in the empty courtyard.</color>",
  ui_story_5054_50540203_16_dialog_content = "Hahaha! Hahaha—!",
  ui_story_5054_50540203_17_dialog_content = "I knew I shouldn't come back for the humiliation.",
  ui_story_5054_50540203_18_dialog_content = "<color=#a8886f>You leave the ruin as soon as you can see. In between the debris, an elderly awaits the savior in his mind.</color>",
  ui_story_5054_50540301_1_dialog_content = "<color=#a8886f>Noises of explosions, screams, pounding hearts, and hard weapons impaling soft objects blast out all around...</color>",
  ui_story_5054_50540301_2_dialog_content = "<color=#a8886f>Giant wings kick up one gale after another, blowing dust onto the faces of people fleeing the scene.</color>",
  ui_story_5054_50540301_3_dialog_content = "<color=#a8886f>Sweat, tears, and blood quickly overwhelm the perfume worn by a young noblewoman. She and a young nobleman watch everything unfold in fear...</color>",
  ui_story_5054_50540301_4_option_content = "Over here, quickly!",
  ui_story_5054_50540301_5_dialog_content = "Thank you for showing us a way out! B-But what's going on here?",
  ui_story_5054_50540301_6_dialog_content = "Insurrection! A premeditated insurrection!",
  ui_story_5054_50540301_7_dialog_content = "My God of Light... Why would anyone do that in Lumopolis?",
  ui_story_5054_50540301_8_dialog_content = "Don't you remember the consequences for those who opposed Schwartz's rule, miss?",
  ui_story_5054_50540301_9_dialog_content = "House Pyrrhus recently, then House Gautier, and House Montague before that...",
  ui_story_5054_50540301_10_dialog_content = "You mean the exiled houses?",
  ui_story_5054_50540301_11_dialog_content = "Oh my... I heard there's a secret cabal of survivors planning their revenge...",
  ui_story_5054_50540301_12_dialog_content = "This is madness! They have all gone mad!",
  ui_story_5054_50540301_13_dialog_content = "Revenge is only a pretense for them who sought to dethrone! Blinded by vengeance will only make you vulnerable to manipulation!",
  ui_story_5054_50540301_14_dialog_content = "(Secret cabal? Dethrone?)",
  ui_story_5054_50540301_15_dialog_content = "Now's not the time to mull over it. We have to run!",
  ui_story_5054_50540301_16_dialog_content = "<color=#a8886f>The pair leaves before you can ask them anything. You look in their direction only to see them surrounded by insurgents...</color>",
  ui_story_5054_50540302_1_dialog_content = "<color=#a8886f>You're familiar with the way from the square back to the Schwartz mansion. And you know, there once was a tower here, now reduced to dust.</color>",
  ui_story_5054_50540302_2_dialog_content = "<color=#a8886f>Between the rocks and debris comes the hoarse, excited voice of an elderly.</color>",
  ui_story_5054_50540302_3_dialog_content = "You! It's you!",
  ui_story_5054_50540302_4_dialog_content = "(Who's that in front of him?)",
  ui_story_5054_50540302_5_dialog_content = "You're finally here to see me!",
  ui_story_5054_50540302_6_dialog_content = "I'm Sharona Kartima. Do you know me?",
  ui_story_5054_50540302_7_dialog_content = "Sharona, what a pretty name... The prophecy gave me the ability to recognize you, but wouldn't reveal you have such a beautiful name.",
  ui_story_5054_50540302_8_dialog_content = "Prophecy?",
  ui_story_5054_50540302_9_dialog_content = "<color=#a8886f>The elderly survey the surrounding cautiously before speaking with a low voice.</color>",
  ui_story_5054_50540302_10_dialog_content = "In the basement of my old house is a Kartima heirloom, a great katana called Azure Flame.",
  ui_story_5054_50540302_11_dialog_content = "It is now yours. Take Azure Flame and finish what you're supposed to finish!",
  ui_story_5054_50540302_12_dialog_content = "Azure Flame? I saw a sword in Uncle Mime's study with the same name…",
  ui_story_5054_50540302_13_dialog_content = "How dare that imposter take what didn't belong to him!",
  ui_story_5054_50540302_14_dialog_content = "But don't worry, no matter whether he kept Azure Flame, it belongs to you!",
  ui_story_5054_50540302_15_dialog_content = "Only you can unlock its power!",
  ui_story_5054_50540302_16_dialog_content = "Go, my child, hurry!",
  ui_story_5054_50540302_17_dialog_content = "<color=#a8886f>Sharona is still lost, but you know that 12 years from now, Commander Sharona will wield a sword called the Azure Flame.</color>"
}
return config
